const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const getProductionModel=()=>window.TimingChartProductionController?.model;
function hiddenSignalIds(model=getProductionModel()){return new Set((model?.document?.signals||[]).filter(signal=>signal.display?.visible===false).map(signal=>signal.id));}
function selectedEntry(model=getProductionModel()){return $$('.row[data-signal]').find(row=>(row.dataset.commentId||row.dataset.signal)===model?.selection?.id);}
function selectedSignal(model=getProductionModel()){return model?.selection?.id||window.TimingChartProductionController?.selectors?.getSignals?.()[0]?.id||'';}
function selectedKind(model=getProductionModel()){return selectedEntry(model)?.dataset.kind||'binary';}
function selectedComment(model=getProductionModel()){return window.TimingChartProductionController?.selectors?.getComments?.().find(comment=>comment.id===model?.selection?.id);}
function esc(value){return String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');}
function selectedSignalModel(model=getProductionModel()){return window.TimingChartProductionController?.selectors?.getSignal?.(selectedSignal(model));}
function derivedRows(signal){const values=[...(signal?.values||[])].sort((a,b)=>Number(a.start)-Number(b.start));return values.map((value,index)=>({value,index,duration:index<values.length-1?Number(values[index+1].start)-Number(value.start):null,end:index<values.length-1?Number(values[index+1].start):null}));}

function signalToolbar(model=getProductionModel()){const controller=window.TimingChartProductionController;const signalId=selectedSignal(model);const signal=controller?.selectors?.getSignal?.(signalId);const role=signal?.role||'internal';const roleClass=role==='output'?'out':role==='internal'?'wire':'in';const roleLabel=role==='output'?'o':role==='internal'?'wire':'i';const next=controller?.getNextSignalValueInsertion?.(signalId);const addState=next===null?' disabled title="変更点を追加できる空きcycleがありません"':` title="Cycle ${next} に変更点を追加"`;const validation=model.validation?.length?`<span style="color:#b22">● ${esc(model.validation[0].message||model.validation[0].code)}</span>`:'';return `<div class="selected-line">選択中の信号:　${esc(signal?.display?.name||signal?.name||signalId)} <span class="role ${roleClass}">${roleLabel}</span> ${validation}</div><div class="toolbar-line"><button class="mini-btn primary" data-editor-action="add"${addState}>＋ 変更点を追加</button><button class="mini-btn" data-editor-action="duplicate">▣ 行を複製</button><button class="mini-btn" data-editor-action="delete">🗑 行を削除</button><button class="mini-btn" data-editor-action="import">⇩ インポート...</button><button class="mini-btn" data-editor-action="export">⇧ エクスポート...</button><button class="mini-btn" data-editor-action="refresh">⟳ プレビュー更新</button></div>`}
function editorInput(signal,index,field,value,type='text'){return `<input data-editor-index="${index}" data-editor-field="${field}" value="${esc(value)}" type="${type}" style="width:100%;border:0;background:transparent;text-align:center;font:inherit;padding:0">`}
function binaryPanel(model=getProductionModel()){const signal=selectedSignalModel(model),rows=derivedRows(signal),selected=model.editor?.rowIndex??rows.length-1;return signalToolbar(model)+`<table><thead><tr><th>□</th><th>#</th><th>Start (cycle)</th><th>Value</th><th>Duration (cycles)</th><th>End (cycle)</th><th>コメント</th></tr></thead><tbody>${rows.map(({value,index,duration,end})=>`<tr class="${index===selected?'selected-row':''}" data-editor-index="${index}"><td>${index===selected?'☑':'□'}</td><td class=center>${index+1}</td><td class=center>${editorInput(signal,index,'start',value.start,'number')}</td><td class=center>${editorInput(signal,index,'value',value.value)}</td><td class=center>${duration??'—'}</td><td class=center>${end??'—'}</td><td>${editorInput(signal,index,'comment',value.comment||'')}</td></tr>`).join('')}</tbody></table><div style="margin-top:8px;color:#5c6878">合計: ${rows.length} 行（終端は自動延長されます）</div>`}
function busPanel(model=getProductionModel()){const signal=selectedSignalModel(model),rows=derivedRows(signal),selected=model.editor?.rowIndex??rows.length-1;return signalToolbar(model)+`<table><thead><tr><th>□</th><th>#</th><th>Start (cycle)</th><th>Value</th><th>Display format</th><th>Duration (cycles)</th><th>End (cycle)</th><th>コメント</th></tr></thead><tbody>${rows.map(({value,index,duration,end})=>`<tr class="${index===selected?'selected-row':''}" data-editor-index="${index}"><td>${index===selected?'☑':'□'}</td><td class=center>${index+1}</td><td class=center>${editorInput(signal,index,'start',value.start,'number')}</td><td class=center>${editorInput(signal,index,'value',value.value)}</td><td class=center>${signal.displayFormat==='hex'?'Hex':signal.displayFormat}</td><td class=center>${duration??'—'}</td><td class=center>${end??'—'}</td><td>${editorInput(signal,index,'comment',value.comment||'')}</td></tr>`).join('')}</tbody></table>`}
function statePanel(model=getProductionModel()){const signal=selectedSignalModel(model),rows=derivedRows(signal),selected=model.editor?.rowIndex??rows.length-1;return signalToolbar(model)+`<table><thead><tr><th>□</th><th>#</th><th>Start (cycle)</th><th>State</th><th>Color</th><th>Duration (cycles)</th><th>End (cycle)</th><th>コメント</th></tr></thead><tbody>${rows.map(({value,index,duration,end})=>`<tr class="${index===selected?'selected-row':''}" data-editor-index="${index}"><td>${index===selected?'☑':'□'}</td><td class=center>${index+1}</td><td class=center>${editorInput(signal,index,'start',value.start,'number')}</td><td class=center>${editorInput(signal,index,'value',value.value)}</td><td class=center>Auto</td><td class=center>${duration??'—'}</td><td class=center>${end??'—'}</td><td>${editorInput(signal,index,'comment',value.comment||'')}</td></tr>`).join('')}</tbody></table>`}
function clockField(label,field,value,type='number'){return `<div class="field"><label>${label}</label><input data-clock-field="${field}" value="${esc(value)}" type="${type}"></div>`}
function clockSelect(label,field,value,options){return `<div class="field"><label>${label}</label><select data-clock-field="${field}">${options.map(option=>`<option ${String(option).toLowerCase()===String(value).toLowerCase()?'selected':''}>${option}</option>`).join('')}</select></div>`}
function clockPanel(model=getProductionModel()){const signal=selectedSignalModel(model),generator=signal?.generator||{},counter=signal?.edgeCounter||{},timeline=model.document.timeline||{};const name=signal?.display?.name||signal?.name||signal?.id||'—';return `<div class="selected-line">選択中の信号:　${esc(name)}　種別: Clock</div><div class="toolbar-line"><select class="mini-btn" data-clock-action="preset"><option value="">∿ プリセット</option><option value="standard">Standard</option><option value="half">Half Rate</option><option value="delayed">Delayed</option></select><button class="mini-btn" data-clock-action="duplicate">▣ 複製</button><button class="mini-btn" data-clock-action="import">⇩ インポート...</button><button class="mini-btn" data-clock-action="export">⇧ エクスポート...</button><button class="mini-btn" data-clock-action="refresh">⟳ プレビュー更新</button></div><div class="clock-form">${clockField('Start (cycle)','start',generator.start??0)}${clockField('Period (cycles)','period',generator.period??1)}${clockField('Duty (%)','duty',(generator.duty??0.5)*100)}${clockField('Phase (cycles)','phase',generator.phase??0)}${clockSelect('Initial level','initialLevel',generator.initial??0,['0','1'])}${clockSelect('Edge基準','edgeReference',timeline.edge||'rising',['Rising','Falling'])}</div><div class="edge-box"><b>エッジ番号表示</b><div class="edge-grid" style="margin-top:8px">${clockSelect('Show','edgeCounter.show',counter.show===false?'OFF':'ON',['ON','OFF'])}${clockSelect('Mode','edgeCounter.mode',counter.mode||'rising',['Rising','Falling','Both'])}${clockField('Start number','edgeCounter.startNumber',counter.startNumber??1)}${clockSelect('Count from','edgeCounter.countFrom',counter.countFrom||'signal-start',['signal-start','selected-edge','marker','visible-range-start'])}${clockField('Show every','edgeCounter.labelEvery',counter.labelEvery??1)}${clockSelect('Position','edgeCounter.position',counter.position||'above',['Above','Below'])}${clockField('Offset X','edgeCounter.offset.x',counter.offset?.x??0)}${clockField('Offset Y','edgeCounter.offset.y',counter.offset?.y??-6)}</div></div>`}
function commentPanel(model=getProductionModel()){const comment=selectedComment(model)||window.TimingChartProductionController?.selectors?.getComments?.()[0]||{id:'',title:'',body:''};return `<div class="selected-line">選択中: Comment Row　${esc(comment.title)}</div><div class="toolbar-line"><button class="mini-btn" data-comment-action="duplicate">複製</button><button class="mini-btn" data-comment-action="delete">削除</button></div><div class="clock-form" style="grid-template-columns:1fr 2fr"><div class="field"><label>Title（左パネル用）</label><input data-comment-field="title" value="${esc(comment.title)}"></div><div class="field"><label>Body（タイミングチャート用）</label><input data-comment-field="body" value="${esc(comment.body)}"></div></div>`}
function timeGroupPanel(model=getProductionModel()){
  const controller=window.TimingChartProductionController; const start=Number(model.timeSelection?.rangeStart); const end=Number(model.timeSelection?.rangeEnd); const hasRange=Number.isInteger(start)&&Number.isInteger(end)&&end>start; const groups=controller?.selectors?.getTimeGroups?.()||[];
  const create=hasRange?`<div class="toolbar-line"><button class="mini-btn primary" data-time-group-action="create">＋ 選択範囲をグループ化</button><span style="color:#5c6878">${start}–${end} / ${end-start} cycles</span></div>`:'';
  if(!groups.length&&!hasRange)return '';
  const rows=groups.map(group=>`<tr data-time-group-id="${esc(group.id)}"><td><button class="mini-btn" data-time-group-action="toggle">${group.presentation?.collapsed?'＋':'−'}</button></td><td><input data-time-group-field="category" value="${esc(group.category||'')}" placeholder="Type"></td><td><input data-time-group-field="name" value="${esc(group.name)}"></td><td><input type="number" data-time-group-field="start" value="${group.start}"></td><td><input type="number" data-time-group-field="end" value="${group.end}"></td><td>${group.duration}</td><td><input data-time-group-field="comment" value="${esc(group.comment||'')}"></td><td>${esc(group.state)} <button class="mini-btn" data-time-group-action="reveal">表示</button><button class="mini-btn" data-time-group-action="delete">削除</button></td></tr>`).join('');
  return `<div class="section" data-time-groups-panel><h3>Time Groups</h3>${create}<table><thead><tr><th></th><th>Type</th><th>Name</th><th>Start</th><th>End</th><th>Duration</th><th>Comment</th><th>State</th></tr></thead><tbody>${rows||'<tr><td colspan="8">Time Groupはありません。</td></tr>'}</tbody></table></div>`;
}
function signalPanel(model=getProductionModel()){const kind=selectedKind(model);const editor=kind==='clock'?clockPanel(model):kind==='bus'?busPanel(model):kind==='state'?statePanel(model):kind==='comment'?commentPanel(model):binaryPanel(model);return editor+timeGroupPanel(model)}
function annotationTypeLabel(type){return ({range:'↔ 範囲',marker:'↕ マーカー',text:'▣ テキスト',callout:'▣ コールアウト',dependency:'↝ 依存関係',verticalLine:'│ 縦線',bracket:'⌜ ブラケット',highlight:'□ 背景'})[type]||type}
function annotationPoint(anchor,model=getProductionModel()){if(!anchor)return '—';if(anchor.point==='cycle-boundary')return `${anchor.cycle}`;const signal=window.TimingChartProductionController?.selectors?.getSignal?.(anchor.signal);const point=anchor.point==='rising'?'↑':anchor.point==='falling'?'↓':anchor.point==='transition-center'?'↕':anchor.point||'';const name=signal?.display?.name||signal?.name||signal?.id||anchor.signal||'—';const value=(signal?.values||[]).find(item=>Number(item.start)===Number(anchor.cycle));const valueLabel=value&&signal?.type!=='binary'?` = ${value.value}`:'';return `${esc(name)}${esc(valueLabel)} ${esc(point)} (${esc(anchor.cycle)})`.replace('  ',' ')}
function annotationOffset(annotation){const anchor=annotation.anchor||annotation.start||annotation.from;return [anchor?.offset?.x||0,anchor?.offset?.y||0]}
function annotationPanel(model=getProductionModel()){const annotations=model.document.annotations||[];const position=annotation=>({top:'上',canvas:'キャンバス',background:'背景'}[annotation.position]||annotation.position||'キャンバス');const anchorButton=(annotation,key)=>{const anchor=key==='start'?(annotation.start||annotation.from||annotation.anchor):(annotation.end||annotation.to);if(!anchor)return '<span>—</span>';return `<button class="mini-btn" data-annotation-anchor-action="${key}">${annotationPoint(anchor,model)}</button>`;};return `<div class="toolbar-line"><button class="mini-btn primary" data-annotation-action="add">＋ 注釈を追加</button><button class="mini-btn" data-annotation-action="duplicate">▣ 行を複製</button><button class="mini-btn" data-annotation-action="delete">🗑 行を削除</button><button class="mini-btn" data-annotation-action="refresh">⟳ プレビュー更新</button></div><table><thead><tr><th>□</th><th>#</th><th>種類</th><th>Start</th><th>End</th><th>ラベル / 本文</th><th>配置先</th><th>X</th><th>Y</th><th>色</th><th>コメント</th></tr></thead><tbody>${annotations.map((annotation,index)=>{const [x,y]=annotationOffset(annotation);return `<tr class="${model.selection?.kind==='annotation'&&model.selection.id===annotation.id?'selected-row':''}" data-annotation-id="${esc(annotation.id)}"><td>${model.selection?.id===annotation.id?'☑':'□'}</td><td>${index+1}</td><td>${esc(annotationTypeLabel(annotation.type))}</td><td>${anchorButton(annotation,'start')}</td><td>${anchorButton(annotation,'end')}</td><td><input data-annotation-field="label" value="${esc(annotation.label||'')}"></td><td><select data-annotation-field="position"><option ${annotation.position==='canvas'?'selected':''}>canvas</option><option ${annotation.position==='top'?'selected':''}>top</option><option ${annotation.position==='background'?'selected':''}>background</option></select></td><td><input type="number" data-annotation-field="offset.x" value="${x}"></td><td><input type="number" data-annotation-field="offset.y" value="${y}"></td><td><input type="color" data-annotation-field="color" value="${esc(annotation.color||'#1473e6')}"></td><td><input data-annotation-field="comment" value="${esc(annotation.comment||'')}"></td></tr>`}).join('')}</tbody></table>`}
function problemSeverity(issue){if(issue.severity==='error')return'err';if(issue.severity==='info')return'info';return /invalid|missing|duplicate|unsupported|outside|negative|overflow|mismatch|undefined/.test(issue.code||'')?'err':'warn'}
function problemsPanel(model=getProductionModel()){const controller=window.TimingChartProductionController;const issues=controller?.getProblems?.(model.document)||[];model.validation=issues;const errors=issues.filter(issue=>problemSeverity(issue)==='err').length;const warnings=issues.filter(issue=>problemSeverity(issue)==='warn').length;const infos=issues.filter(issue=>problemSeverity(issue)==='info').length;return `<div class="toolbar-line"><button class="mini-btn primary">すべて (${issues.length?issues.length+1:0})</button><button class="mini-btn">エラー (${errors})</button><button class="mini-btn">警告 (${issues.length?warnings+1:warnings})</button><button class="mini-btn">情報 (${infos})</button><button class="mini-btn">すべての信号⌄</button><div style="flex:1"></div><button class="mini-btn" data-problem-action="refresh">⟳ 最新の状態に更新</button></div><table><thead><tr><th>□</th><th>#</th><th>重要度</th><th>種類</th><th>信号 / 行</th><th>区間 (cycle)</th><th>内容</th><th>推奨対応</th><th>自動修正</th><th>状態</th></tr></thead><tbody>${issues.length?issues.map((issue,index)=>`<tr data-problem-path="${esc(issue.path)}"><td>□</td><td>${index+1}</td><td><span class="badge ${problemSeverity(issue)}">${problemSeverity(issue)==='err'?'エラー':problemSeverity(issue)==='info'?'情報':'警告'}</span></td><td>${esc(issue.displayType||issue.code)}</td><td>${esc(issue.id||issue.field||'document')}</td><td>${esc(issue.range||'—')}</td><td>${esc(issue.message)}</td><td>${esc(issue.recommendation||'該当パスを確認してください')}</td><td>${esc(issue.auto||'—')}</td><td>未解決</td></tr>`).join(''):`<tr><td colspan="10">問題はありません。Semantic ModelとAnchorを検証済みです。</td></tr>`}</tbody></table>`}
function jsonPanel(model=getProductionModel()){const controller=window.TimingChartProductionController;const json=JSON.stringify(controller?.getSerializableDocument?.()||model.document,null,2);const issues=controller?.getProblems?.(model.document)||[];const summary=`{\n  "formatVersion": "1.0.0",\n  "timeBase": "${model.document.timeline.timeBase}",\n  "referenceClock": "${model.document.timeline.referenceClock}",\n  "edge": "${model.document.timeline.edge}",\n  "signals": [\n    {"type":"clock","id":"clk"},\n    {"type":"signal","id":"req_valid"},\n    {"type":"bus","id":"req_addr[7:0]","width":8},\n    {"type":"state","id":"state[1:0]","width":2},\n    {"type":"comment","title":"Read latency"}\n  ]\n}`;return `<div class="toolbar-line"><button class="mini-btn" data-json-action="format">整形</button><button class="mini-btn" data-json-action="validate">検証</button><span style="color:${issues.length?'#b22':'#2e9550'}">● ${issues.length?`${issues.length}件の問題`:'有効なJSONです'}</span><div style="flex:1"></div><button class="mini-btn" data-json-action="import">⇩ インポート...</button><button class="mini-btn" data-json-action="export">⇧ エクスポート...</button><button class="mini-btn" data-json-action="copy">コピー</button></div><div class="json-wrap"><pre class="code" data-json-summary="reference">${esc(summary)}</pre><pre class="code" data-json-document="canonical" hidden>${esc(json)}</pre><div class="tree">⌄ {} ルート<br>　formatVersion: "1.0.0"<br>　timeBase: "${esc(model.document.timeline.timeBase)}"<br>　referenceClock: "${esc(model.document.timeline.referenceClock)}"<br>　edge: "${esc(model.document.timeline.edge)}"<br>⌄ signals [9]<br>　› 0: {type:"clock", id:"clk"}<br>　› 1: {type:"signal", id:"req_valid"}<br>　› 2: {type:"bus", id:"req_addr[7:0]", width:8}<br>› annotations [${model.document.annotations?.length||0}]<br>› transactions [${model.document.transactions?.length||0}]</div></div>`}
function transactionPanel(model=getProductionModel()){const controller=window.TimingChartProductionController;const transactions=model.document.transactions||[];const signals=(model.document.signals||[]).filter(signal=>signal.type!=='commentRow');const issues=controller?.getProblems?.(model.document)||[];const status=transaction=>issues.some(issue=>issue.id===transaction.id||issue.code?.includes('transaction'))?'● 問題':'● 有効';return `<div class="toolbar-line"><button class="mini-btn primary" data-transaction-action="add">＋ Transaction</button><button class="mini-btn" data-transaction-action="duplicate">複製</button><button class="mini-btn" data-transaction-action="delete">削除</button></div><table><thead><tr><th>□</th><th>#</th><th>Transaction名</th><th>Lane</th><th>Start</th><th>End</th><th>Duration</th><th>Linked Signals</th><th>Phases (JSON)</th><th>Status</th><th>Comment</th></tr></thead><tbody>${transactions.length?transactions.map((transaction,index)=>`<tr class="${model.selection?.kind==='transaction'&&model.selection.id===transaction.id?'selected-row':''}" data-transaction-id="${esc(transaction.id)}"><td>${model.selection?.id===transaction.id?'☑':'□'}</td><td>${index+1}</td><td><input data-transaction-field="name" value="${esc(transaction.name)}"></td><td><input data-transaction-field="lane" value="${esc(transaction.lane||'default')}"></td><td><input type="number" data-transaction-field="start" value="${transaction.start}"></td><td><input type="number" data-transaction-field="end" value="${transaction.end}"></td><td>${transaction.end-transaction.start}</td><td><select multiple size="3" data-transaction-field="linkedSignals">${signals.map(signal=>`<option value="${esc(signal.id)}" ${(transaction.linkedSignals||[]).includes(signal.id)?'selected':''}>${esc(signal.display?.name||signal.name||signal.id)}</option>`).join('')}</select></td><td><textarea data-transaction-field="phases">${esc(JSON.stringify(transaction.phases||[],null,0))}</textarea></td><td>${status(transaction)}</td><td><input data-transaction-field="comment" value="${esc(transaction.comment||'')}"></td></tr>`).join(''):`<tr><td colspan="11">Transactionはありません。Ribbonまたは＋ Transactionから追加できます。</td></tr>`}</tbody></table>`}
function renderTransactionCanvas(model=getProductionModel()){const host=$('#transactionCanvas .transaction-canvas');if(!host)return;const timeline=model.document.timeline||{};const timelineStart=Number(timeline.start??0);const timelineEnd=Number(timeline.end??timeline.cycleCount??1);const timelineLength=Math.max(1,timelineEnd-timelineStart);const transactions=model.document.transactions||[];const issues=window.TimingChartProductionController?.getProblems?.(model.document)||[];const meta=$$('#transactionCanvas .canvas-meta span');if(meta[0])meta[0].textContent=`Time base: ${timeline.timeBase||'cycle'}`;if(meta[1])meta[1].textContent=`${timelineStart} - ${timelineEnd} ${timeline.timeBase==='ns'?'ns':'cycles'}`;host.innerHTML=transactions.length?transactions.map(transaction=>{const phases=Array.isArray(transaction.phases)?transaction.phases:[];const transactionIssues=issues.filter(issue=>issue.id===transaction.id||issue.code?.includes('transaction'));const phaseMarkup=phases.map((phase,index)=>{const start=Number(phase.start);const end=Number(phase.end);const left=((start-timelineStart)/timelineLength)*100;const width=((end-start)/timelineLength)*100;const invalid=phase.end<=phase.start||start<Number(transaction.start)||end>Number(transaction.end);return `<div class="phase${invalid?' invalid':''}" data-phase-id="${esc(`${transaction.id}:${index}`)}" data-transaction-id="${esc(transaction.id)}" title="${esc(`${phase.name}: ${phase.start}-${phase.end}`)}" style="position:absolute;left:${left}%;width:${Math.max(0,width)}%;box-sizing:border-box;">${esc(phase.name)}<br>${Math.max(0,end-start)} cycles</div>`}).join('');const left=((Number(transaction.start)-timelineStart)/timelineLength)*100;const width=((Number(transaction.end)-Number(transaction.start))/timelineLength)*100;return `<div class="txn-lane" data-transaction-id="${esc(transaction.id)}"><b>${esc(transaction.name)}</b><div class="txnbar" data-transaction-start="${transaction.start}" data-transaction-end="${transaction.end}" data-invalid="${transactionIssues.length?'true':'false'}" style="position:relative;width:100%;"><div class="txn-window" style="position:absolute;left:${left}%;width:${Math.max(0,width)}%;height:100%;border:1px solid ${transactionIssues.length?'#c43d3d':'#4f8fea'};box-sizing:border-box;"></div>${phaseMarkup}</div></div>`}).join(''):'<div class="txn-lane"><b>No transactions</b><div class="transaction-empty">Add a transaction to render the shared semantic time axis.</div></div>';if(!host.dataset.phaseBinding){host.dataset.phaseBinding='true';host.addEventListener('click',event=>{const phase=event.target.closest('[data-phase-id]');const row=event.target.closest('[data-transaction-id]');const id=phase?.dataset.transactionId||row?.dataset.transactionId;if(id)window.TimingChartProductionController?.actions.selectTransaction(id);});}}
function ensureBookmarkTab(model=getProductionModel()){
  const host=$('#bottomTabs'); if(!host)return;
  let tab=host.querySelector('[data-tab="bookmarks"]');
  if(!tab){tab=document.createElement('button');tab.className='btab';tab.dataset.tab='bookmarks';tab.textContent='Bookmarks';host.insertBefore(tab,host.querySelector('.follow'));tab.addEventListener('click',()=>window.TimingChartProductionController?.actions.setBottomTab('bookmarks'));}
  tab.hidden=!(model.document.bookmarks||[]).length && model.view.tab!=='bookmarks';
}
function bookmarkPanel(model=getProductionModel()){
  const controller=window.TimingChartProductionController;const bookmarks=[...(model.document.bookmarks||[])].sort((a,b)=>Number(a.start)-Number(b.start)||String(a.id).localeCompare(String(b.id)));
  return `<div class="toolbar-line"><button class="mini-btn primary" data-bookmark-action="add">＋ Bookmark</button><button class="mini-btn" data-bookmark-action="delete">削除</button><span style="color:#5c6878">${bookmarks.length}件</span></div><table><thead><tr><th>□</th><th>Name</th><th>Time / Cycle</th><th>Comment</th></tr></thead><tbody>${bookmarks.length?bookmarks.map(bookmark=>`<tr class="${model.selection?.kind==='bookmark'&&model.selection.id===bookmark.id?'selected-row':''}" data-bookmark-id="${esc(bookmark.id)}"><td><button class="mini-btn" data-bookmark-action="jump">${model.selection?.id===bookmark.id?'☑':'□'}</button></td><td><input data-bookmark-field="name" value="${esc(bookmark.name)}"></td><td><input type="number" data-bookmark-field="start" value="${bookmark.start}"></td><td><textarea data-bookmark-field="comment" rows="1">${esc(bookmark.comment||'')}</textarea></td></tr>`).join(''):'<tr><td colspan="4">Bookmarkはありません。</td></tr>'}</tbody></table>`;
}
function renderBottom(model=getProductionModel()){ensureBookmarkTab(model);const bc=$('#bottomContent'); if(model.view.tab==='signal')bc.innerHTML=signalPanel(model); else if(model.view.tab==='annotation')bc.innerHTML=annotationPanel(model); else if(model.view.tab==='problems')bc.innerHTML=problemsPanel(model); else if(model.view.tab==='json')bc.innerHTML=jsonPanel(model); else if(model.view.tab==='bookmarks')bc.innerHTML=bookmarkPanel(model); else bc.innerHTML=transactionPanel(model); bc.dataset.renderedTab=model.view.tab;}
