(()=>{let bookmarkUiFrame=0;const install=()=>{const controller=window.TimingChartProductionController;if(!controller)return setTimeout(install,0);controller.renderBookmarkUi=model=>{if(bookmarkUiFrame)return;bookmarkUiFrame=requestAnimationFrame(()=>{bookmarkUiFrame=0;ensureBookmarkTab(model);document.querySelectorAll('#bottomTabs [data-tab]').forEach(button=>button.classList.toggle('active',button.dataset.tab===model.view.tab));if(model.view.tab==='bookmarks')renderBottom(model);});};};install();})();
function renderComments(model=getProductionModel()){const comments=window.TimingChartProductionController?.selectors?.getComments?.()||[];$$('.row[data-kind="comment"]').forEach((row,index)=>{const comment=comments[index];if(!comment)return;row.dataset.commentId=comment.id;row.dataset.signal=comment.id;const name=$('.row-name',row);if(name)name.textContent=comment.title;});$$('#cycleCanvas .wave-row').filter(row=>!$('.trace',row)).forEach((row,index)=>{const comment=comments[index];if(!comment)return;const label=$('.signal-label',row);if(label)label.textContent=comment.title;const body=$('.comment-body,.latency',row);if(body)body.textContent=comment.body;});}
function renderLabelParts(signal,model,controller,context='tree'){const source=signal.source||{instancePath:[],signalName:signal.name||signal.id};const path=Array.isArray(source.instancePath)?source.instancePath:[];const mode=model.document.layout.pathDisplayMode||'signalOnly';const scope=Array.isArray(model.view.scope)?model.view.scope:[];let visiblePath=[];if(mode==='full')visiblePath=path;else if(mode==='relative'){let index=0;while(index<scope.length&&index<path.length&&scope[index]===path[index])index++;visiblePath=path.slice(index);}const stripRange=value=>String(value??'').replace(/\[\d+\s*:\s*\d+\]$/,'');const signalName=stripRange(signal.display?.name||source.signalName||signal.name||signal.id);const range=source.msb===undefined&&signal.width===undefined?'':`[${source.msb??Number(signal.width)-1}:${source.lsb??0}]`;const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));if(context==='canvas')return `<span class="signal-name-part">${esc(signalName)}</span>${range?`<span class="bus-width-part">${esc(range)}</span>`:''}`;if(mode==='splitColumns')return `<span class="instance-path-part hierarchy-instance-column" style="display:inline-block;width:35%;text-align:${model.document.layout.instancePathAlign||'left'}">${esc(visiblePath.join('.')||'—')}</span><span class="signal-name-part hierarchy-signal-column" style="display:inline-block;width:40%">${esc(signalName)}</span><span class="bus-width-part hierarchy-bus-column" style="display:inline-block;width:25%;text-align:${model.document.layout.busWidthAlign||'left'}">${esc(range)}</span>`;return `${visiblePath.length?`<span class="instance-path-part hierarchy-instance-column">${esc(visiblePath.join('.'))}.</span>`:''}<span class="signal-name-part">${esc(signalName)}</span>${range?`<span class="bus-width-part bus-width-column"${model.document.layout.busWidthMode==='alignedColumn'?' style="display:inline-block;min-width:56px;text-align:'+((model.document.layout.busWidthAlign)||'left')+'"':''}>${esc(range)}</span>`:''}`;}
function renderLayoutBindings(model=getProductionModel()){const controller=window.TimingChartProductionController;const signals=controller?.selectors?.getSignals?.()||[];const byId=new Map(signals.map(signal=>[signal.id,signal]));$$('.row[data-signal]').forEach(row=>{const signal=byId.get(row.dataset.signal);if(!signal)return;const role=$('.role',row);if(role){role.className=`role ${signal.role==='output'?'out':signal.role==='internal'?'wire':'in'}`;role.textContent=signal.role==='output'?'o':signal.role==='internal'?'wire':'i';}const name=$('.row-name',row);if(name){name.innerHTML=renderLabelParts(signal,model,controller,'tree');name.title=controller.hierarchy?.getFullPath?.(signal)||signal.name;const alignment=signal.type==='bus'?(model.document.layout.busWidthAlign||'left'):(model.document.layout.signalNameAlign||'left');if(alignment==='left')name.style.removeProperty('text-align');else name.style.textAlign=alignment;}});const groupByRow=new Map((model.document.signalGroups||[]).flatMap(group=>(group.rows||[]).map(id=>[id,group])));$$('#cycleCanvas .wave-row').forEach(row=>{const id=row.dataset.signalId||row.dataset.signal||$('.signal-label',row)?.dataset.signalId||$('.signal-label',row)?.textContent?.trim();const signal=byId.get(id);const group=groupByRow.get(id);if(signal){const label=$('.signal-label',row);if(label){label.innerHTML=renderLabelParts(signal,model,controller,'canvas');label.dataset.signalId=signal.id;}}if(group?.style?.background){row.style.backgroundColor=group.style.background;row.style.opacity=group.style.opacity??1;}});}
function bindEditor(model=getProductionModel()){const controller=window.TimingChartProductionController;const content=$('#bottomContent');if(!controller||!content)return;content.querySelectorAll('[data-clock-field]').forEach(input=>input.addEventListener('change',()=>controller.actions.updateClock(model.selection.id,input.dataset.clockField,input.value)));content.querySelectorAll('[data-comment-field]').forEach(input=>input.addEventListener('change',()=>controller.actions.updateComment(model.selection.id,input.dataset.commentField,input.value)));content.querySelector('[data-comment-action="duplicate"]')?.addEventListener('click',()=>controller.actions.duplicateComment(model.selection.id));content.querySelector('[data-comment-action="delete"]')?.addEventListener('click',()=>controller.actions.deleteComment(model.selection.id));content.querySelector('[data-editor-action="refresh"]')?.addEventListener('click',()=>controller.render());content.querySelector('[data-annotation-action="add"]')?.addEventListener('click',()=>controller.actions.addAnnotation());content.querySelector('[data-annotation-action="duplicate"]')?.addEventListener('click',()=>controller.actions.duplicateAnnotation(model.selection.id));content.querySelector('[data-annotation-action="delete"]')?.addEventListener('click',()=>controller.actions.deleteAnnotation(model.selection.id));content.querySelector('[data-annotation-action="refresh"]')?.addEventListener('click',()=>controller.render());content.querySelectorAll('[data-annotation-id]').forEach(row=>row.addEventListener('click',event=>{if(!event.target.closest('input,select,button'))controller.actions.selectAnnotation(row.dataset.annotationId);}));content.querySelectorAll('[data-annotation-field]').forEach(input=>input.addEventListener('change',()=>{const id=input.closest('[data-annotation-id]')?.dataset.annotationId||model.selection.id;controller.actions.updateAnnotation(id,input.dataset.annotationField,input.type==='checkbox'?input.checked:input.value);}));content.querySelector('[data-json-action="format"]')?.addEventListener('click',()=>{model.jsonFormatRevision=(model.jsonFormatRevision||0)+1;controller.render();});content.querySelector('[data-json-action="validate"]')?.addEventListener('click',()=>{model.validation=controller.getProblems(model.document,{force:true});controller.render();});content.querySelector('[data-json-action="copy"]')?.addEventListener('click',()=>{controller.controlBehaviorAudit&&(controller.controlBehaviorAudit.clipboardRevision=(controller.controlBehaviorAudit.clipboardRevision||0)+1);void navigator.clipboard?.writeText(JSON.stringify(controller.getSerializableDocument(),null,2)).catch(()=>{});});content.querySelector('[data-json-action="export"]')?.addEventListener('click',async()=>{window.TimingChartLastJsonExport=controller.prepareSaveText().text;const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([window.TimingChartLastJsonExport],{type:'application/json'}));link.download='timing-chart.tcd.json';link.click();URL.revokeObjectURL(link.href);});content.querySelector('[data-json-action="import"]')?.addEventListener('click',()=>{const input=document.createElement('input');input.type='file';input.accept='.json,.tcd';input.addEventListener('change',async()=>{const file=input.files?.[0];if(file)await controller.actions.openText(await file.text(),{fileName:file.name,unsavedDecision:'discard'});});input.click();});content.querySelectorAll('[data-transaction-id]').forEach(row=>row.addEventListener('click',event=>{if(!event.target.closest('input,select,button'))controller.actions.selectTransaction(row.dataset.transactionId);}));content.querySelectorAll('[data-transaction-field]').forEach(input=>input.addEventListener('change',()=>{const id=input.closest('[data-transaction-id]')?.dataset.transactionId||model.selection.id;controller.actions.updateTransaction(id,input.dataset.transactionField,input.value);}));content.querySelector('[data-transaction-action="add"]')?.addEventListener('click',()=>controller.actions.addTransaction());content.querySelector('[data-transaction-action="delete"]')?.addEventListener('click',()=>controller.actions.deleteTransaction(model.selection.id));content.querySelector('[data-transaction-action="duplicate"]')?.addEventListener('click',()=>controller.actions.duplicateTransaction(model.selection.id));}
function renderInspector(model=getProductionModel()){const i=$('#inspectorBody');const annotation=model.selection?.kind==='annotation'?(model.document.annotations||[]).find(item=>item.id===model.selection.id):null;if(model.view.tab==='annotation'&&annotation){const anchor=annotation.anchor||annotation.start||annotation.from||{};const labelOffset=annotation.labelOffset||{x:0,y:0};const labelStyle=annotation.labelStyle||{wrap:false,maxWidth:240,lineHeight:1.2,align:'center'};i.innerHTML=`<div class="section"><h3>Annotation</h3><div class="prop"><span>ID</span><b>${esc(annotation.id)}</b></div><div class="prop"><span>Type</span><b>${esc(annotation.type)}</b></div><div class="prop"><span>Label</span><input data-annotation-field="label" value="${esc(annotation.label||'')}"></div><div class="prop"><span>Color</span><input data-annotation-field="color" value="${esc(annotation.color||'#1473e6')}"></div><div class="prop"><span>Position</span><b>${esc(annotation.position||'canvas')}</b></div><div class="prop"><span>Comment</span><input data-annotation-field="comment" value="${esc(annotation.comment||'')}"></div></div><div class="section"><h3>Anchor</h3><div class="prop"><span>Signal</span><b>${esc(anchor.signal||'')}</b></div><div class="prop"><span>Cycle</span><b>${anchor.cycle??''}</b></div><div class="prop"><span>Point</span><b>${esc(anchor.point||'')}</b></div><div class="prop"><span>Offset X</span><input data-annotation-field="offset.x" value="${anchor.offset?.x||0}"></div><div class="prop"><span>Offset Y</span><input data-annotation-field="offset.y" value="${anchor.offset?.y||0}"></div></div><div class="section"><h3>Label Layout</h3><div class="prop"><span>Label Offset X</span><input data-annotation-field="labelOffset.x" value="${labelOffset.x||0}"></div><div class="prop"><span>Label Offset Y</span><input data-annotation-field="labelOffset.y" value="${labelOffset.y||0}"></div><div class="prop"><span>Wrap</span><input type="checkbox" data-annotation-field="labelStyle.wrap" ${labelStyle.wrap?'checked':''}></div><div class="prop"><span>Max Width</span><input data-annotation-field="labelStyle.maxWidth" type="number" value="${labelStyle.maxWidth||240}"></div><div class="prop"><span>Line Height</span><input data-annotation-field="labelStyle.lineHeight" type="number" step="0.1" value="${labelStyle.lineHeight||1.2}"></div><div class="prop"><span>Align</span><select data-annotation-field="labelStyle.align"><option ${labelStyle.align==='left'?'selected':''}>left</option><option ${labelStyle.align==='center'?'selected':''}>center</option><option ${labelStyle.align==='right'?'selected':''}>right</option></select></div></div>`}else if(model.view.tab==='annotation'){i.innerHTML='<div class="section"><h3>Annotation</h3><span>注釈を選択してください</span></div>'}else if(model.view.tab==='problems'){i.innerHTML=`<div class="section"><h3>概要</h3>🔴 エラー　2<br><br>🟠 警告　3<br><br>🔵 情報　1</div><div class="section"><h3>自動チェック設定</h3><label><input type=checkbox checked> 幅チェック</label><br><label><input type=checkbox checked> 未定義値チェック</label><br><label><input type=checkbox checked> レイテンシチェック</label></div>`}else if(model.view.tab==='json'){i.innerHTML=`<div class="section"><h3>JSON Document</h3><div class="prop"><span>Time base</span><b>cycle</b></div><div class="prop"><span>Ref clock</span><b>clk</b></div><div class="prop"><span>Signals</span><b>9</b></div><div class="prop"><span>Annotations</span><b>${model.document.annotations?.length||0}</b></div></div><div class="section"><h3>検証</h3><span style="color:#2e9550">● 有効なJSONです</span></div>`}else{const signal=selectedSignal(model);const kind=selectedKind(model);i.innerHTML=`<div class="section"><h3>信号プロパティ</h3><div class="prop"><span>名前</span><input value="${signal}"></div><div class="prop"><span>種別</span><input value="${kind}"></div><div class="prop"><span>可視性</span><select><option>表示</option><option>非表示</option></select></div></div><div class="section"><h3>表示</h3><label><input type=checkbox checked> 波形を表示</label><br><label><input type=checkbox checked> ラベルを表示</label></div>`}}
