function modelDrivenReconcileCycleRows(model=getProductionModel()){return modelDrivenReconcileCycleRowsKeyed(model);}
function modelDrivenReconcileCycleRowsKeyed(model=getProductionModel()){
  const canvas=$('#cycleCanvas'),wave=$('.wave',canvas);if(!wave)return;
  const signals=new Map((model.document.signals||[]).map(signal=>[signal.id,signal]));
  const existing=new Map([...wave.querySelectorAll(':scope > .wave-row')].map(row=>[row.dataset.signalId||row.dataset.signal,row]));
  const metrics=window.TimingChartProductionController.renderMetrics ||= {waveDromRenders:0,geometryBuilds:0,geometryCacheHits:0,waveCacheHits:0,rowCreates:0,rowRemoves:0};
  const used=new Set();
  const groupClass=signal=>signal.role==='output'?'band-output':signal.role==='internal'?'band-internal':'band-command';
  const createRow=signal=>{
    const row=document.createElement('div');metrics.rowCreates+=1;
    row.className=`wave-row ${groupClass(signal)}`;
    row.dataset.signalId=signal.id;row.dataset.signal=signal.id;row.dataset.kind=signal.type==='commentRow'?'comment':signal.type;
    const icon=document.createElement('span');icon.className='canvas-icon role';row.append(icon);
    const label=document.createElement('span');label.className='signal-label';row.append(label);
    if(signal.type==='commentRow'){const body=document.createElement('span');body.className='comment-body';row.append(body);}
    else{const trace=document.createElement('span');trace.className='trace';row.append(trace);}
    return row;
  };
  const updateRow=(row,signal,group)=>{
    const kind=signal.type==='commentRow'?'comment':signal.type;
    if(row.dataset.kind!==kind || Boolean(row.querySelector('.trace'))!== (kind!=='comment')){const replacement=createRow(signal);row.replaceWith(replacement);row=replacement;}
    row.className=`wave-row ${groupClass(signal)}`;row.dataset.signalId=signal.id;row.dataset.signal=signal.id;row.dataset.kind=kind;row.dataset.groupId=group.id;
    const icon=row.querySelector('.canvas-icon');if(icon){icon.className=`canvas-icon role ${kind==='comment'?'comment':signal.role==='output'?'out':signal.role==='internal'?'wire':'in'}`;icon.textContent=kind==='comment'?'▣':signal.role==='output'?'o':signal.role==='internal'?'wire':'i';}
    const label=row.querySelector('.signal-label');if(label){label.textContent=kind==='comment'?signal.title:signal.display?.name||signal.name||signal.id;label.dataset.signalId=signal.id;}
    const body=row.querySelector('.comment-body');if(body)body.textContent=signal.body||'';
    return row;
  };
  for(const group of model.document.signalGroups||[]) for(const id of group.rows||[]){const signal=signals.get(id);if(!signal)continue;let row=existing.get(id)||createRow(signal);row=updateRow(row,signal,group);wave.append(row);used.add(id);}
  for(const row of wave.querySelectorAll('.wave-row')){const id=row.dataset.signalId||row.dataset.signal;if(!used.has(id)){metrics.rowRemoves+=1;row.remove();}}
}
