      button.addEventListener('keydown',event=>{if(event.key!=='ArrowLeft'&&event.key!=='ArrowRight')return;event.preventDefault();const current=Boolean(controller.model.document.signalGroups.find(item=>item.id===group.id)?.collapsed);if((event.key==='ArrowLeft'&&!current)||(event.key==='ArrowRight'&&current))controller.actions.setGroupCollapsed(group.id,!current);});
