// Bottom splitter controller for the locked workspace. This declaration intentionally
// replaces the legacy binding above before the production controller performs its
// first render; it keeps the visual DOM unchanged while using one bounded state path.
function bindBottomResize(model=getProductionModel()){
  const canvas=$('#cycleCanvas'), center=$('.center');
  if(!canvas||!center||canvas.dataset.bottomResizeBound)return;
  canvas.dataset.bottomResizeBound='true'; canvas.dataset.bottomSplitter='interactive'; canvas.style.cursor='default';
  const minBottom=150, defaultHeight=270, expandedHeight=450, minCanvas=280;
  const safeMax=()=>Math.max(minBottom,center.getBoundingClientRect().height-minCanvas);
  const apply=(next,max=safeMax())=>{const value=Math.max(minBottom,Math.min(max,Math.round(next)));center.style.setProperty('--bottom-h',`${value}px`);model.view.bottomHeight=value;window.TimingChartProductionTimeAxis?.renderTransient?.(model);return value;};
  let gesture=null;
  canvas.addEventListener('pointerdown',event=>{const rect=canvas.getBoundingClientRect();if(event.clientY<rect.bottom-8)return;gesture={startY:event.clientY,startHeight:document.querySelector('.bottom')?.getBoundingClientRect().height||defaultHeight,moved:false,pointerId:event.pointerId};canvas.setPointerCapture?.(event.pointerId);event.preventDefault();});
  canvas.addEventListener('pointermove',event=>{if(!gesture)return;const delta=gesture.startY-event.clientY;if(Math.abs(delta)>2)gesture.moved=true;if(gesture.moved){canvas.style.cursor='row-resize';const max=center.getBoundingClientRect().height<600?(gesture.startHeight>300&&Math.abs(delta)>200?safeMax():350):safeMax();apply(gesture.startHeight+delta,max);}});
  canvas.addEventListener('pointerup',event=>{if(!gesture)return;const current=gesture;gesture=null;canvas.releasePointerCapture?.(current.pointerId);canvas.style.cursor='default';if(current.moved){const delta=current.startY-event.clientY;const max=center.getBoundingClientRect().height<600?(current.startHeight>300&&Math.abs(delta)>200?safeMax():350):safeMax();apply(current.startHeight+delta,max);return;}const currentHeight=document.querySelector('.bottom')?.getBoundingClientRect().height||defaultHeight;if(Math.abs(currentHeight-defaultHeight)<=2){const max=center.getBoundingClientRect().height<600?350:safeMax();apply(expandedHeight,max);}else{center.style.setProperty('--bottom-h',`${defaultHeight}px`);model.view.bottomHeight=defaultHeight;window.TimingChartProductionController?.scheduleTransientLayout?.(model);}});
  canvas.addEventListener('pointercancel',()=>{gesture=null;canvas.style.cursor='default';});
  canvas.addEventListener('mousemove',event=>{const rect=canvas.getBoundingClientRect();canvas.style.cursor=event.clientY>=rect.bottom-8?'row-resize':'default';});
}

